/* global __dirname */
const fs = require("node:fs");
const path = require("node:path");
const { spawnSync } = require("node:child_process");

const root = path.resolve(__dirname, "..");
const route = path.join(root, "app", "dev", "seed", "[name].tsx");
const content =
  '// Generated by scripts/qa-routes.cjs; do not edit.\nexport { default } from "@/dev/SeedRoute";\n';

function prepare() {
  if (fs.existsSync(route) && fs.readFileSync(route, "utf8") !== content) {
    throw new Error("Refusing to overwrite an unrecognized QA route.");
  }
  fs.mkdirSync(path.dirname(route), { recursive: true });
  fs.writeFileSync(route, content);
}

function remove() {
  if (fs.existsSync(route)) {
    if (fs.readFileSync(route, "utf8") !== content) {
      throw new Error("Refusing to remove an edited QA route.");
    }
    fs.unlinkSync(route);
  }
  // Only these known directories, and only when empty. Never recursively delete.
  for (const dir of [path.dirname(route), path.dirname(path.dirname(route))]) {
    if (fs.existsSync(dir) && fs.readdirSync(dir).length === 0) fs.rmdirSync(dir);
  }
}

switch (process.argv[2]) {
  case "prepare":
    prepare();
    break;
  case "remove":
    remove();
    break;
  case "start": {
    prepare();
    const result = spawnSync(
      process.execPath,
      [require.resolve("expo/bin/cli"), "start", "--clear", ...process.argv.slice(3)],
      {
        cwd: root,
        env: { ...process.env, SEWSURE_QA_ROUTES: "1" },
        stdio: "inherit",
      },
    );
    if (result.error) throw result.error;
    process.exitCode = result.status ?? 1;
    break;
  }
  default:
    throw new Error("Use prepare, remove or start.");
}
